UPDATE companies SET description='Yost Foods operates from Brunswick, Ohio, where it was founded in 1991 by Bill Yost as an industrial food brokerage. The family-owned company transitioned into custom ingredient manufacturing to meet customer demand for greater flexibility and dependable supply at scale.

Today the facility runs multiple production rooms separated for dry, wet, and kettle-cooking processes. Core capabilities include liquid mixing for sauces and marinades, ribbon and paddle mixing for dry blends, and kettle cooking for bases, caramelized sugars, purees, and pepper blends. High-volume capacity and smart automation support scalable production, with packaging options ranging from bags and bag-in-box to drums, pails, and totes.

The company serves national food manufacturers across categories such as sauces, dressings, and marinades; refrigerated and ready-to-eat foods; frozen meals and pizzas; snacks, candy, and nuts; and ice cream and frozen desserts. Yost works directly with R&D teams, food scientists, and culinary innovators from concept through commercial launch.

A family-owned, long-term mindset drives the company''s differentiation: collaborative development that ensures performance in real production, fast sampling and rapid revisions, repeatable batches with process control, and guidance for clean-label certifications including kosher, organic, gluten-free, and non-GMO. The quality program maintains an SQF Excellent rating and a regulatory department focused on documentation.', certifications=ARRAY['SQF (Safe Quality Food) Excellent rating','Kosher certification','Organic certification','Gluten-free certification','Non-GMO certification','NSA certification']::text[], profile='{"capabilities": ["Liquid mixing for sauces, marinades, and hot sauces", "Ribbon and paddle mixing for dry blends and snack bases", "Kettle cooking for bases, caramelized sugar, purees, and pepper blends", "Custom dry and wet ingredient system development", "Collaborative formulation development with R&D teams", "Scale-up and production support including plant trials", "Clean label and certification support (kosher, organic, gluten-free, non-GMO, NSA)", "Packaging in bags, bag-in-box, drums, pails, and totes", "Automation for efficiency and repeatability", "Separate production rooms for dry, wet, and kettle processes"], "industries": ["Sauces, dressings, and marinades", "Refrigerated and ready-to-eat foods", "Frozen meals and pizzas", "Snacks, candy, and nuts", "Ice cream and frozen desserts"], "materials": ["Snack seasonings", "Dry sauces", "Bases", "Purees", "Marinades", "Caramelized sugar", "Pepper blends"], "equipment": ["Liquid mixers", "Ribbon mixers", "Paddle mixers", "Kettle cookers"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Fast sampling and rapid revisions to keep project timelines moving", "Repeatable batches, process control, and scalable solutions for growing volumes", "Guidance for kosher, organic, gluten-free, non-GMO, and NSA certifications", "Flexible packaging formats: bags, bag-in-box, drums, pails, and totes", "Multiple production rooms organized by product and process type"], "facts_used": ["Founded 1991 by Bill Yost -> /about-us, /", "Family-owned -> /, /about-us, /quality", "Headquarters Brunswick, Ohio -> /, /about-us", "Started as industrial food brokerage -> /about-us", "Transitioned to custom ingredient manufacturing -> /about-us", "Multiple production rooms for dry, wet, kettle cooking -> /", "Liquid mixing for sauces, marinades, hot sauces -> /", "Ribbon and paddle mixing for dry blends -> /", "Kettle cooking for bases, caramelized sugar, purees, pepper blends -> /", "High-volume capacity and smart automation -> /", "Packaging: bags, bag-in-box, drums, pails, totes -> /", "Industries: sauces/dressings/marinades, refrigerated/RTE, frozen meals/pizzas, snacks/candy/nuts, ice cream/frozen desserts -> /", "Works with R&D teams, food scientists, culinary innovators -> /", "Collaborative development, fast sampling, rapid revisions -> /", "Repeatable batches, process control, scalable solutions -> /", "Clean label certification support: kosher, organic, gluten-free, non-GMO, NSA -> /", "SQF Excellent rating -> /quality", "FSMA and GFSI mentioned -> /quality", "Regulatory department for documentation -> /quality"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "custom ingredient manufacturer", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='yost-foods' AND approved AND profile IS NULL;
UPDATE companies SET description='Zen By Design was established in 2001 in Scottsdale, Arizona, as a family-run venture dedicated to crafting meditation furniture. The company began with the intention of bringing more comfort and harmony to meditation practice, hand-building each piece in its Scottsdale workshop.

The company produces a line of meditation chairs—including the Tantra Chair, Anahata, Rama, Samurai, and the portable Zenfu zafu—along with meditation candles. Every chair is handcrafted from eco-friendly materials; artisans individually select each piece of wood and fabric, and the ergonomic design provides a gentle sacral tilt and back support for extended sitting. Over more than two decades, the workshop has supplied tens of thousands of meditators worldwide.

Customers range from individual practitioners to ashrams and meditation centers across nearly every nation. Notable clients have included Dr. Deepak Chopra, Dr. Andrew Weil, The Oprah Winfrey Show, Jack Canfield, and His Holiness the Dalai Lama. The company serves both newcomers to meditation and lifelong practitioners seeking relief from physical discomfort during practice.

Zen By Design emphasizes that its furniture is made in the USA with no expense spared for excellence, and it maintains a 100 percent customer-satisfaction record. The team is available seven days a week, year-round, and the founders say they are motivated by the desire to create the finest products at a fair price, believing that furniture created with love can be felt and enjoyed for a lifetime.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted furniture manufacturing", "Wood selection and fabrication", "Fabric selection and upholstery", "Ergonomic design for meditation seating", "Custom product configuration", "Customer support (7 days/week, 365 days/year)"], "industries": ["Meditation and mindfulness", "Wellness and spiritual practice", "Yoga", "Home furniture", "Ashrams and meditation centers"], "materials": ["Wood", "Fabric", "Eco-friendly materials"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted in Scottsdale, Arizona, using eco-friendly materials", "Ergonomic design with sacral tilt and back support for longer meditation", "100% customer satisfaction history with 7-day-a-week, 365-day service", "Family-run operation with artisans who have been with the company since its start", "Made in the USA with individually selected wood and fabric"], "facts_used": ["Founded 2001 in Scottsdale, Arizona -> db", "Handcrafted meditation chairs and furniture -> /", "Eco-friendly materials used -> /", "Family-run venture -> /about", "Artisans have been with company from beginning -> /about", "100% customer satisfaction -> /about", "Available 7 days/week, 365 days/year -> /about", "Clients include Deepak Chopra, Andrew Weil, Oprah Winfrey Show, Jack Canfield, Dalai Lama -> /about", "Tens of thousands of meditators worldwide over 21-year history -> /about", "Ergonomic design with sacral tilt and back support -> /", "Made in USA -> /", "Products: The Tantra Chair, Anahata, Rama, Samurai, Zenfu, Zen Candle -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Zen By Design is a Scottsdale, Arizona, maker of meditation chairs and other meditation furniture", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='zen-by-design' AND approved AND profile IS NULL;
UPDATE companies SET description='Zephyrus Electronics & Fabrication was founded in 1985 in Tulsa, Oklahoma, on a commitment to innovation, durability, and customer satisfaction. The company operates as a single integrated supplier for electronics and metal fabrication, combining design, assembly, and finishing under one roof.

The shop provides in-house PCB design and assembly, wire harness fabrication, and the manufacture of plastic, polycarbonate, and metal enclosures and brackets. Its metal fabrication facility runs a Strippit 1000xp 20 CNC turret punch, an AMADA 8025 NC press brake, Miller Syncrowave 300 welders, and a Timesaver 22 series deburring and finishing line. Engraving and silk‑screening capabilities include Gravograph IS7000/IS8000 engravers and an Epilog Laser Fusion system. Wire processing uses a Schleuniger Eco Strip 9380 cutter/stripper and Molex and AMP terminal presses.

Zephyrus serves OEM and industrial customers across a range of sectors, building custom control panels, complex wiring harnesses, and precision‑machined enclosures to specification. The company emphasizes rapid prototyping and quick turnaround on design changes to support product development cycles.

The firm’s stated differentiation is its integrated, one‑stop approach—streamlining production, reducing lead times, and ensuring quality from concept to completion—with all work performed in the United States.', certifications=ARRAY[]::text[], profile='{"capabilities": ["PCB design and assembly", "Wire harness assembly", "CNC turret punching", "Press brake forming", "Welding (TIG/MIG)", "Deburring and surface finishing", "Laser engraving", "Mechanical engraving", "Silk screening", "Plastic and polycarbonate enclosure fabrication", "Metal enclosure and bracket fabrication", "Wire cutting and stripping", "Terminal pressing"], "industries": ["OEM", "Industrial"], "materials": ["Plastic", "Polycarbonate", "Metal", "Sheet metal", "Wire"], "equipment": ["Schleuniger Eco Strip 9380 wire cut and strip", "Molex 9002-50 wire terminal press", "AMP Model G wire terminal press", "RIGOL digital oscilloscope", "Strippit 1000xp 20 CNC turret punch", "AMADA 8025 NC press brake", "Miller Syncrowave 300 weld machines", "Timesaver 22 series debur and surface finishing", "Paintfill metal engraving", "Gravograph IS7000 and IS8000 engravers", "Epilog Laser Fusion laser engraver"], "volume": "Prototype to production", "lead_time": "", "tolerances": "", "built_on": ["Integrated electronics and metal fabrication under one roof", "In-house PCB design, assembly, and wire harnessing", "Rapid prototyping and quick turnaround on changes", "All manufacturing performed in the USA"], "facts_used": ["Founded in 1985 -> db, /, /about", "Headquarters Tulsa, Oklahoma -> db, /", "Integrated electronics and metal fabrication services -> /", "PCB design and assembly, wire harnessing, enclosure fabrication -> /", "Equipment list (Strippit, AMADA, Miller, Timesaver, Schleuniger, Molex, AMP, Gravograph, Epilog) -> /", "Engraving and silk screening services -> /", "Serves OEM and industrial applications -> /", "Rapid prototyping and quick turnaround -> /", "Made in USA claim -> /", "One-stop shop differentiation -> /, /about"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We are a one-stop solution for electronics and metal fabrication, offering end-to-end support from design to production.", "founded_year": "1985", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='zephyrus-electronics-fabrication' AND approved AND profile IS NULL;
UPDATE companies SET description='Zibtek, a software development services firm, is headquartered in Salt Lake City, Utah. The company was founded in 2009 by entrepreneurs who had previously founded, built, and exited multiple ventures. They applied that experience to helping clients navigate digital transformation through custom software solutions.

The firm delivers full-cycle custom software development, including web application development, mobile app development, API development, microservices architecture, and ERP system development. It also provides staff augmentation, quality assurance and testing, DevOps, project management, and design services. Development teams are available onshore, nearshore, and offshore to align with client budgets and timelines.

Zibtek serves clients across sectors such as healthcare and safety, social media, productivity tools, and financial services. Notable engagements include building a workplace screening portal for FormFox, developing the private family social app Awsm (formerly Stoke), creating a cross-platform journaling application for Promptly Journals, and supplying scalable development resources for Academy Mortgage.

The company distinguishes itself through end-to-end product ownership, a practical agile methodology that emphasizes sprint-based delivery and continuous feedback, and a rigorous hiring process that yields autonomous yet communicative engineers. Clients receive a single point of contact paired with a project manager, and the firm''s local presence in Salt Lake City enables on-site collaboration and faster turnaround.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom software development", "Web application development", "Mobile application development", "API development", "Microservices architecture", "ERP system development", "Staff augmentation", "Quality assurance and testing", "DevOps", "Project management", "Design", "React Native development"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["End-to-end product ownership", "Practical agile methodology with sprint-based delivery", "In-country, nearshore, and offshore delivery models", "Rigorous hiring process for autonomous, communicative engineers", "Single point of contact paired with dedicated project manager"], "facts_used": ["Founded in 2009 -> db", "Headquartered in Salt Lake City, Utah -> db", "Founders had experience founding, building, exiting multiple companies -> /", "Services: custom software development, web app, mobile app, API, microservices, ERP, staff augmentation, QA/QC, DevOps, project management, design -> /", "Delivery models: onshore, nearshore, offshore -> /", "Clients: FormFox (workplace screening portal), Stoke/Awsm (family social app), Promptly Journals (journaling app), Academy Mortgage (mortgage) -> /", "Differentiators: end-to-end product ownership, practical agile methodology, rigorous hiring, single point of contact with project manager, local presence -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Since 2009, we''ve used our real-world experience of founding, building, and exiting multiple companies to lead the digital transformation of our clients through custom software development services.", "founded_year": "2009", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='zibtek-software-company-in-salt-lake-city' AND approved AND profile IS NULL;
UPDATE companies SET description='Zim''s Bagging Company operates from Prichard, West Virginia, where it was founded in 1964.

The company converts and prints plastic film, foam, and bubble roll-stock into bags, pouches, and mailers at two facilities — a Main Facility and a SoftPack Facility. Equipment includes forming, folding, cutting, and sealing machinery, plus a 10-color, 59-inch web W&H Miraflex II printing press capable of photo-quality front-and-back printing on roll-stock for automated form-fill-seal lines. Custom options such as tapes, handles, wickets, punched holes, labels, and bar codes can be added to any order.

Customers span automotive, e-commerce, food, home and garden, industrial, and medical markets. Typical products include poly bags, wicket bags, PowerPack mailer bags, printed roll stock, and foam and bubble cushioning, all tailored to non-standard specifications.

Zim''s differentiates itself by specializing in value-added, custom-designed, non-standard packaging rather than commodity items, a focus the company says stems from its deep experience in the flexible packaging industry.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Film converting", "Foam converting", "Bubble packaging converting", "Flexographic printing (up to 10-color, 59-inch web)", "Custom bag forming, folding, cutting, sealing", "Tape, handle, wicket, punched hole, label, and bar code application", "Printed roll stock for form-fill-seal", "Wicket bag manufacturing", "PowerPack mailer bag manufacturing", "Poly bag manufacturing"], "industries": ["Automotive", "E-commerce", "Food", "Home and garden", "Industrial", "Medical"], "materials": ["Plastic film", "Foam", "Bubble"], "equipment": ["W&H Miraflex II printing press (10-color, 59-inch web)", "Forming, folding, cutting, and sealing machinery"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Value-added, custom-designed, non-standard packaging focus", "10-color, 59-inch web W&H Miraflex II printing press", "Two facilities (Main and SoftPack) with forming, folding, cutting, sealing machinery", "Custom options: tapes, handles, wickets, punched holes, labels, bar codes", "Front and back photo-quality printing on roll-stock for form-fill-seal"], "facts_used": ["Founded 1964 -> db", "Headquarters Prichard, West Virginia -> db", "Two facilities: Main Facility and SoftPack Facility -> homepage", "Machinery for forming, folding, cutting, sealing -> homepage", "10-color, 59-inch web W&H Miraflex II printing press -> homepage", "Industries served: automotive, e-commerce, food, home and garden, industrial, medical -> homepage", "Custom options: tapes, handles, wickets, punched holes, labels, bar codes -> homepage", "Value-added, custom designed, non-standard packaging differentiation -> homepage", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "converting and printing film, foam and bubble packaging materials", "founded_year": "1964", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/zims-bagging-company/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='zim-s-bagging-company' AND approved AND profile IS NULL;
UPDATE companies SET description='Today the company is headquartered in Premstaetten/Graz, Austria, with a co-headquarters in Munich, Germany, and a significant U.S. presence in Novi, Michigan.

The company designs and manufactures semiconductor-based light emitters, optical sensors, CMOS integrated circuits, and related software, along with traditional lighting technologies for automotive and specialty applications. Its product portfolio includes VCSELs, infrared LEDs, UV-C LEDs, time-of-flight sensors, LiDAR lasers, and LED driver ICs, produced through global manufacturing capabilities and protected by a portfolio of around 12,000 patents.

ams OSRAM serves the automotive, industrial, medical, consumer electronics, mobile and wearables, lighting, and computing sectors. In automotive, its SYNIOS P2222 LEDs set a new standard for signaling, while its OSIRE E3030 RGB LEDs enable advanced interior lighting. In consumer health, Korean baby-care brand UPANG adopts the company''s UV-C LED technology for bottle sterilization. The firm also supplies optical interconnects for AI data centers and LiDAR solutions for autonomous vehicles.

The company positions itself as a "Photonics Powerhouse," differentiating through its combination of light emission, detection, and intelligence — what it calls Digital Photonics. Its mission emphasizes pioneering lighting and sensing technologies that make the world safer, smarter, and more sustainable, backed by a culture of innovation, trust, and speed.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Semiconductor light emitter manufacturing", "Optical sensor manufacturing", "CMOS IC design and manufacturing", "VCSEL manufacturing", "Time-of-Flight sensor manufacturing", "LED driver IC manufacturing", "Wafer-level chip-scale packaging (WLCSP)", "Thin-film VCSEL technology", "SPAD (Single Photon Avalanche Diode) technology", "TDC (Time-to-Digital Converter) technology", "LiDAR laser manufacturing", "UV-C LED manufacturing", "Infrared LED manufacturing", "Automotive LED signaling solutions", "Automotive interior RGB LED solutions", "Optical interconnects for AI data centers", "Eye-safe LED driver ICs for AR/VR", "Multi-zone dToF sensing", "Histogram-based signal processing", "I3C/I2C/SPI interface integration"], "industries": ["Automotive & mobility", "Industrial", "Medical & health", "Mobile & wearables", "Lighting", "Computing", "AI Photonics", "LiDAR", "Consumer electronics"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["120 years of industry experience since the OSRAM brand''s founding in 1906", "Global manufacturing capabilities with around 18,500 employees worldwide", "Portfolio of approximately 12,000 patents and patent applications", "Distinct Digital Photonics portfolio combining light emitters, sensors, and intelligence", "Proven track record in automotive, industrial, medical, and consumer electronics markets"], "facts_used": ["Founded 1906 (OSRAM brand) -> /about-us", "Headquartered in Premstaetten/Graz, Austria with co-headquarters in Munich, Germany -> /about-us", "Approximately 18,500 employees worldwide -> /about-us", "Revenue EUR 3.3 billion in 2025 -> /about-us", "Portfolio of ~12,000 patents and patent applications -> /about-us", "Products: semiconductor light emitters, optical sensors, CMOS ICs, software, traditional lighting -> /about-us", "Industries served: automotive, industrial, medical, consumer electronics -> /about-us", "Vision: Inspire people with innovative light and sensor solutions -> /about-us", "Mission: Pioneer differentiating lighting and sensing technologies -> /about-us", "Product highlights: SYNIOS P2222, FIREFLY SFH 4030B, TMF8829, TMF8806, AS1181, OSLON Compact RM, OSIRE E3030 -> /", "Applications: Automotive & mobility, Industrial, Medical & health, Mobile & wearables, Lighting, Computing -> /", "Customer example: UPANG uses UV-C LED for baby bottle sterilization -> /", "AI Photonics for optical interconnects -> /", "LiDAR advancement with 5-junction edge-emitting laser -> /", "ALIYOS Bond Vision for vehicle interiors -> /", "US location: Novi, Michigan -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are a Photonics Powerhouse. Our distinct portfolio of advanced light and sensor technologies sets us apart in our industry. It includes high-quality semiconductor-based light emitters, optical sensors, CMOS ICs and software as well as a range of traditional lighting technologies for automotive and special applications.", "founded_year": "1906", "employee_count": "18500", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ams-osram' AND approved AND profile IS NULL;
UPDATE companies SET description='Pan Pacific Plastics Mfg Inc was founded in 1981 and is headquartered in Hayward, California. The company is independently owned and operated by a woman and is certified by the National Minority Supplier Development Council (NMSDC). It emphasizes family values among its employees and has built a reputation over four decades in the packaging industry.

The company manufactures and imports a full line of packaging bags made from paper and plastic. At its Hayward facility, Pan Pacific performs plastic extrusion, printing, and converting in an expanded manufacturing plant. It also maintains manufacturing partnerships across Asia to provide additional paper and plastic product capacity. Domestic production offers low minimums — as little as 100 pounds of plastic extrusion — with lead times of approximately four to six weeks; import lead times run ten to twelve weeks.

Pan Pacific serves a broad range of industries including grocery, retail, promotional, industrial, agricultural, food service, airline, travel, and hospitality. Its customer base includes Fortune 500 companies as well as individual homes and businesses worldwide. Product lines cover tamper-evident, retail, food service, industrial, and eco-friendly bags.

The company states its mission is to provide quality service and products at competitive prices while actively creating innovative packaging ideas. Differentiators cited include price protection programs that guarantee pricing and inventory for up to a full calendar year, an in-house graphic art department for artwork proofs and cleanup, and quality control inspections at both factory and warehouse levels. Responsiveness and customer support are described as staples of its business model.', certifications=ARRAY['NMSDC certified (National Minority Supplier Development Council)']::text[], profile='{"capabilities": ["Plastic extrusion", "Printing", "Converting", "Paper bag manufacturing", "Plastic bag manufacturing", "Import sourcing (Asia partnerships)", "Graphic design and artwork services", "Quality control and inspection", "Price protection programs", "Customer support and responsiveness"], "industries": ["Grocery", "Retail", "Promotional", "Industrial", "Agricultural", "Food service", "Airline", "Travel", "Hospitality", "Fortune 500 companies"], "materials": ["Paper", "Plastic", "Polyethylene"], "equipment": [], "volume": "", "lead_time": "4-6 weeks domestic, 10-12 weeks import", "tolerances": "", "built_on": ["Domestic manufacturing with low minimums (100 lbs plastic extrusion)", "Short lead times (4\u20136 weeks domestic, 10\u201312 weeks import)", "Price protection programs guaranteeing pricing up to one year", "In-house graphic art department for artwork proofs and cleanup", "NMSDC-certified minority-owned and woman-owned business"], "facts_used": ["Founded 1981, headquartered Northern California, Hayward facility does plastic extruding, printing, converting -> db, /about-us", "Manufacturing partnerships in Asia for paper and plastic products -> /about-us", "Minority owned and certified NMSDC -> /about-us", "Woman owned -> /about-us", "Over 100+ years collective staff experience -> /", "Low domestic minimums 100 lbs plastic extrusion -> /", "Lead times 4-6 wee